<script setup lang="ts">
import {allOptions} from '../../api/options'
import{ref,computed,watch,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{http}from'../../api/http';import{day}from'../../utils/dates';import DishImage from'../../components/DishImage.vue';import type {Row} from '../../shared/records'
import {newRequestKey} from '../../utils/requestKey'
const route=useRoute(),router=useRouter(),elders=ref<Row[]>([]),elderId=ref<number>(),date=ref(day(1)),meal=ref('LUNCH'),type=ref('DINE_IN'),recommendations=ref<Row>({items:[],excluded:[]}),quantities=ref<Record<number,number>>({}),error=ref(''),pending=ref(false),loading=ref(false),address=ref(''),contact=ref(''),phone=ref(''),recurring=ref(false),endDate=ref(day(7)),results=ref<Row[]>([]),requestKey=ref(newRequestKey())
const addresses=ref<Row[]>([]),savedAddress=ref<number>(),addressError=ref('');let addressGeneration=0
watch(elderId,async id=>{const g=++addressGeneration;addresses.value=[];savedAddress.value=undefined;address.value='';contact.value='';phone.value='';addressError.value='';if(!id||!route.path.startsWith('/family'))return;try{const data=await allOptions('/addresses?elderId='+id);if(g!==addressGeneration)return;addresses.value=data;const primary=data.find(a=>a.isDefault);if(primary){savedAddress.value=primary.id;useAddress(primary.id)}}catch(e){if(g===addressGeneration)addressError.value=(e as Error).message}})
function useAddress(id?:number){const a=addresses.value.find(v=>v.id===id);if(a){address.value=a.address;contact.value=a.contactName;phone.value=a.contactPhone}}
const elder=computed(()=>elders.value.find(e=>e.id===elderId.value)),total=computed(()=>recommendations.value.items.reduce((sum:number,item:Row)=>sum+Number(item.effectivePrice)*(Number(quantities.value[item.menuItemId])||0),0).toFixed(2))
onMounted(async()=>{try{elders.value=(await allOptions('/elders?size=100')).filter((e:Row)=>e.status==='ACTIVE'&&e.approvalStatus==='APPROVED');elderId.value=elders.value[0]?.id}catch(e){error.value=(e as Error).message}})
let loadGeneration=0
async function load(){
 const generation=++loadGeneration
 recommendations.value={items:[],excluded:[]};quantities.value={};error.value=''
 if(!elder.value){loading.value=false;return}
 loading.value=true;requestKey.value=newRequestKey()
 try{
  const data=await http.get<never,Row>(`/elders/${elderId.value}/recommendations`,{params:{siteId:elder.value.siteId,date:date.value,mealType:meal.value}})
  if(generation===loadGeneration)recommendations.value=data
 }catch(e){if(generation===loadGeneration)error.value=(e as Error).message}
 finally{if(generation===loadGeneration)loading.value=false}
}
async function submit(){if(pending.value||loading.value||!elder.value)return;pending.value=true;error.value='';try{const items=recommendations.value.items.filter((i:Row)=>Number(quantities.value[i.menuItemId])>0).map((i:Row)=>({menuItemId:i.menuItemId,dishId:i.dishId,quantity:Number(quantities.value[i.menuItemId]),recommendationEventId:i.recommendationEventId}));if(!items.length)throw new Error('请先选择菜品和份数');const body:Row={elderId:elderId.value,siteId:elder.value.siteId,mealType:meal.value,deliveryType:type.value,...(type.value==='DELIVERY'?{deliveryAddress:address.value,contactName:contact.value,contactPhone:phone.value}:{})};if(recurring.value){body.dateFrom=date.value;body.dateTo=endDate.value;body.items=items.map((i:Row)=>({dishId:i.dishId,quantity:i.quantity}));results.value=await http.post('/proxy-orders/recurring',body)}else{body.mealDate=date.value;body.items=items.map(({dishId,...i}:Row)=>i);await http.post('/orders',body,{headers:{'Idempotency-Key':requestKey.value}});await router.push(route.path.startsWith('/community')?'/community/orders':'/family/orders')}}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
watch(()=>[elderId.value,date.value,meal.value],()=>void load())
</script>
<template><section><p class="eyebrow">用心照顾每一餐</p><h1>{{route.path.startsWith('/community')?'协助老人订餐':'为家人订一餐'}}</h1><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert"/><el-empty v-if="!elders.length" description="暂无已审核的老人，请先办理建档与绑定"/><template v-else><div class="toolbar"><el-select v-model="elderId" filterable aria-label="选择老人"><el-option v-for="e in elders" :key="e.id" :value="e.id" :label="e.name"/></el-select><label for="order-date">用餐日期</label><el-input id="order-date" v-model="date" type="date"/><el-select v-model="meal" aria-label="用餐餐次"><el-option label="午餐" value="LUNCH"/><el-option label="晚餐" value="DINNER"/></el-select></div><p>服务网点：{{elder?.siteName}}</p><p v-if="loading" role="status">正在加载所选日期的可售餐品…</p><el-alert v-if="recommendations.warning" :title="recommendations.warning" type="warning" :closable="false"/><p v-if="recommendations.algorithm">推荐算法：{{recommendations.algorithm}} · 配置版本 {{recommendations.configVersion}}</p><div class="info-grid"><article v-for="item in recommendations.items" :key="item.menuItemId" class="content-card"><DishImage :file-id="item.imageFileId" :name="item.dishName"/><h2>{{item.dishName}}</h2><p>食材：{{(item.ingredients??[]).join('、')}}</p><p>原价 ¥{{item.originalPrice}} · 本餐应付单价 <strong>¥{{item.effectivePrice}}</strong></p><p>{{item.reasons.join(' · ')}} · {{item.score==null?'暂未评分':'推荐分 '+item.score}}</p><el-collapse v-if="item.components"><el-collapse-item title="查看推荐分项"><p v-for="(label,key) in {nutrition:'营养匹配',preference:'老人偏好',review:'历史评价',history:'近期选择'}" :key="key">{{label}}：{{Number(item.components[key]).toFixed(1)}} / 100<span v-if="recommendations.weights"> · 权重 {{(Number(recommendations.weights[key])*100).toFixed(0)}}%</span></p><p>排序按各项评分与当前配置权重合成，饮食禁忌在评分前独立检查。</p></el-collapse-item></el-collapse><p>剩余 {{item.remainingQty}} 份</p><label :for="'qty-'+item.menuItemId">选择份数</label><el-input :id="'qty-'+item.menuItemId" v-model="quantities[item.menuItemId]" type="number" min="0" :max="item.remainingQty"/></article></div><el-empty v-if="!loading&&!recommendations.items.length" description="暂无符合已登记饮食要求的可售菜品"/><el-collapse v-if="recommendations.excluded.length"><el-collapse-item title="查看未推荐的菜品及原因"><p v-for="item in recommendations.excluded" :key="item.menuItemId">{{item.dishName}}：{{item.reason}}</p></el-collapse-item></el-collapse>
<section class="content-card" style="margin-top:24px"><div class="form-stack"><label>取餐方式</label><el-radio-group v-model="type"><el-radio value="DINE_IN">堂食</el-radio><el-radio value="TAKEOUT">外带</el-radio><el-radio value="DELIVERY">配送</el-radio></el-radio-group><template v-if="type==='DELIVERY'"><el-alert v-if="addressError" :title="addressError" type="warning" :closable="false"/><template v-if="route.path.startsWith('/family')"><label>选择已保存地址（也可手动填写）</label><el-select v-model="savedAddress" clearable aria-label="常用地址" @change="useAddress"><el-option v-for="a in addresses" :key="a.id" :value="a.id" :label="a.label+' · '+a.address"/></el-select><router-link to="/family/addresses" class="text-link">管理常用地址 →</router-link></template><label for="delivery-address">配送地址</label><el-input id="delivery-address" v-model="address"/><label for="delivery-contact">联系人</label><el-input id="delivery-contact" v-model="contact"/><label for="delivery-phone">联系电话</label><el-input id="delivery-phone" v-model="phone" type="tel"/></template><template v-if="route.path.startsWith('/community')"><el-checkbox v-model="recurring">周期代订（逐日独立订单）</el-checkbox><label v-if="recurring" for="recurring-end">结束日期（最多 7 天）</label><el-input v-if="recurring" id="recurring-end" v-model="endDate" type="date"/></template><h2>{{recurring?'首日参考金额':'本餐应付'}}：¥{{total}}</h2><p>实际金额由系统按订餐时的资格、价格和数量重新核算。</p><el-button type="primary" size="large" :loading="pending" :disabled="loading" @click="submit">{{recurring?'生成逐日订单':'提交订单'}}</el-button><div v-for="result in results" :key="result.date">{{result.date}}：{{result.success?'订餐成功':result.message}}</div></div></section></template></section></template>
